INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q7509852', 'Siege of Bangkok', 'The siege of Bangkok was a key event of the Siamese revolution of 1688, in which the Kingdom of Siam ousted the French from Siam. Following a coup d''état, in which the pro-Western king Narai was replaced by Phetracha, Siamese troops besieged the French fortress in Bangkok for four months.', 1688, 6, NULL, 1688, 11, 13, 'month', 'June 1688 – 13 November 1688', 34, 'https://en.wikipedia.org/wiki/Siege_of_Bangkok'),
  ('Q2280723', 'Burmese–Siamese War of 1785–86', 'The Burmese–Siamese War (1785–1786), known as the Nine Armies'' Wars (Thai: สงครามเก้าทัพ) in Siamese history because the Burmese came in nine armies, was the first war between the Konbaung dynasty of Burma and the Siamese Rattanakosin Kingdom of the Chakri dynasty. King Bodawpaya of Burma pursued an ambitious campaign to expand his dominions into Siam.', 1785, 1, NULL, 1786, 1, NULL, 'month', 'January 1785 – January 1786', 47, 'https://en.wikipedia.org/wiki/Burmese%E2%80%93Siamese_War_(1785%E2%80%931786)'),
  ('Q6407091', 'Laotian Rebellion', 'The Lao Rebellion of 1826–1828 (also known as Anouvong''s Rebellion) was an attempt by King Anouvong (Xaiya Sethathirath V) of the Kingdom of Vientiane to end the suzerainty of Siam and recreate the former kingdom of Lan Xang. In January 1827 the Lao armies of the kingdoms of Vientiane and Champasak moved south and west across the Khorat Plateau, advancing as far as Saraburi, just three days'' march from the Siamese capital of Bangkok.', 1826, NULL, NULL, 1828, NULL, NULL, 'year', '1826–1828', 43, 'https://en.wikipedia.org/wiki/Lao_rebellion_(1826%E2%80%931828)'),
  ('Q4204647', '1833 Sumatra earthquake', 'The 1833 Sumatra earthquake occurred on November 25 at about 22:00 local time, with an estimated magnitude in the range of 8.8–9.2 Mw. It caused a large tsunami that flooded the southwestern coast of the island.', 1833, NULL, NULL, NULL, NULL, NULL, 'year', '1833', 41, 'https://en.wikipedia.org/wiki/1833_Sumatra_earthquake'),
  ('Q7506740', 'Siamese-American Treaty of Amity and Commerce', 'Treaty of Amity and Commerce between His Majesty the Magnificent King of Siam and the United States of America (Thai: หนังสือสัญญาทางพระราชไมตรีประเทศอเมริกันแลประเทศสยามคฤษต์ศักราช๑๘๓๓, Portuguese: Tractado de Amizade, e Commercio entre Sua Magestade o Magnifico Rey de Siam e os Estados Unidos d’America, Chinese: 暹羅國王與雅彌理嘉合省國交結通好貿易之約) or the American–Siamese Roberts Treaty of 1833, was a treaty between Siam or Rattanakosin Kingdom under King Rama III and the United States during the presidency of Andrew Jackson. This treaty established relations between Siam and the United States, being…', 1833, 3, 20, NULL, NULL, NULL, 'day', '20 March 1833', 26, 'https://en.wikipedia.org/wiki/Siamese%E2%80%93American_Treaty_of_Amity_and_Commerce'),
  ('Q745728', 'Bowring Treaty', 'Treaty of Friendship and Commerce between Great Britain and Siam (Thai: หนังสือสัญญากรุงเทพมหานครกับกรุงอังกริษเปนทางไมตรีค้าขายกัน), known colloquially as the Bowring Treaty, was the historic landmark treaty signed between the United Kingdom during the reign of Queen Victoria and the Kingdom of Siam during the reign of King Mongkut on 18 April 1855 at Thonburi, Bangkok. The treaty had tremendous effects on Siamese economy, society and international relations in Thai history, marking the advent of "Modern Siam" in most historiographies, also serving as the model for "Bowring-type" unequal…', 1855, 4, 18, NULL, NULL, NULL, 'day', '18 April 1855', 52, 'https://en.wikipedia.org/wiki/Bowring_Treaty'),
  ('Q4924112', 'Paknam Incident', 'The Paknam Incident was a military engagement fought during the Franco-Siamese crisis in July 1893. While sailing off Paknam on Siam''s Chao Phraya River, three French ships violated Siamese territory and a Siamese fort and a force of gunboats fired warning shots.', 1893, 7, 13, NULL, NULL, NULL, 'day', '13 July 1893', 37, 'https://en.wikipedia.org/wiki/Paknam_incident'),
  ('Q111937469', 'Ngiao Rebellion', 'The Ngiao rebellion (Thai: กบฏเงี้ยว), also called the Phrae City Rebellion and the 1902 Shan rebellion, was an uprising of Tai Yai (Shan, historically known in Thai as Ngiao) people against Siamese rule, in what is now Phrae province in northern Thailand between 25 July and 14 August in 1902. It arose as resistance to centralizing reforms initiated by King Chulalongkorn, particularly the levying of taxes and the adoption of the Monthon Thesaphiban provincial administration system, as well as the partitioning of territory with the British, which forced the Shan to adopt either British or…', 1902, 7, 25, 1904, 5, 22, 'day', '25 July 1902 – 22 May 1904', 26, 'https://en.wikipedia.org/wiki/Ngiao_rebellion'),
  ('Q13021956', 'Franco–Siamese Treaty of 1904', 'The Franco–Siamese Treaty of 1904 (Thai: สนธิสัญญาสยาม–ฝรั่งเศส ร.ศ. 122) was a convention between the Kingdom of Siam during the reign of King Chulalongkorn and France during the presidency of President Émile Loubet.', 1904, 2, 11, NULL, NULL, NULL, 'day', '11 February 1904', 37, 'https://en.wikipedia.org/wiki/Franco-Siamese_Treaty_of_1904'),
  ('Q2119303', 'June 1933 Siamese coup d''état', 'The Siamese coup d’état of June 1933 (Thai: รัฐประหาร 20 มิถุนายน พ.ศ. 2476) took place peacefully on 20 June 1933 in Bangkok and was led was led by Army Colonel Phraya Phahonphonphayuhasena (Phraya Phahon) against the administration of Phraya Manopakorn Nitithada (Phraya Mano).', 1933, 6, 20, NULL, NULL, NULL, 'day', '20 June 1933', 37, 'https://en.wikipedia.org/wiki/June_1933_Siamese_coup_d''%C3%A9tat'),
  ('Q780845', 'Franco-Thai War', 'The Franco-Thai War (October 1940 – 28 January 1941, Thai: กรณีพิพาทอินโดจีน, romanized: Karani Phiphat Indochin; French: Guerre franco-thaïlandaise) was fought between Thailand and Vichy France over certain areas of French Indochina. Negotiations shortly before World War II had shown that the French government was willing to alter the boundaries between Thailand and French Indochina, but only slightly.', 1940, 10, NULL, 1941, 5, 9, 'month', 'October 1940 – 9 May 1941', 67, 'https://en.wikipedia.org/wiki/Franco-Thai_War'),
  ('Q702579', 'Battle of Ko Chang', 'The Battle of Ko Chang took place on 17 January 1941 during the Franco-Thai War. A flotilla of French warships attacked a smaller force of Thai vessels, including a coastal defence ship.', 1941, 1, 16, 1941, 1, 17, 'day', '16 January 1941 – 17 January 1941', 53, 'https://en.wikipedia.org/wiki/Battle_of_Ko_Chang'),
  ('Q1200928', 'Japanese invasion of Thailand', 'The Japanese invasion of Thailand (Thai: การบุกครองไทยของญี่ปุ่น, RTGS: Kan Buk Khrong Thai Khong Yipun; Japanese: 日本軍のタイ進駐, romanized: Nihongun no Tai shinchū) occurred on 8 December 1941. It was briefly fought between the Kingdom of Thailand and the Empire of Japan.', 1941, 12, 8, NULL, NULL, NULL, 'day', '8 December 1941', 61, 'https://en.wikipedia.org/wiki/Japanese_invasion_of_Thailand'),
  ('Q1280169', 'Battle of Prachuap Khiri Khan', 'The Battle of Prachuap Khiri Khan (Thai: ยุทธการที่ประจวบคีรีขันธ์) was an early engagement of the Japanese invasion of Thailand in the Southeast Asian theatre of World War II. It was fought on 8–9 December 1941 at the airfield of Prachuap Khiri Khan, on the coast of the Gulf of Thailand along the Kra Isthmus. The Japanese meant to use Thailand as a base to strike at British possessions in Burma and Malaya and attacked Thailand after it failed to respond to an ultimatum sent by the Japanese government.', 1941, 12, 8, 1941, 12, 9, 'day', '8 December 1941 – 9 December 1941', 37, 'https://en.wikipedia.org/wiki/Battle_of_Prachuap_Khiri_Khan'),
  ('Q19950418', 'Japanese occupation of Thailand', 'Thailand officially adopted a neutral position during World War II until the five hour-long Japanese invasion of Thailand on 8 December 1941, which led to an armistice and military alliance treaty between Thailand and the Empire of Japan in mid-December 1941. At the start of the Pacific War, the Japanese Empire pressured the Thai government to allow the passage of Japanese troops to invade British-held Malaya and Burma.', 1941, NULL, NULL, 1945, NULL, NULL, 'year', '1941–1945', 26, 'https://en.wikipedia.org/wiki/Japanese_occupation_of_Thailand'),
  ('Q4871917', 'Battle of Northern Burma and Western Yunnan', 'Battle of Northern Burma and Western Yunnan (Chinese: 滇西緬北戰役 October 1943 – March 1945) was the name of the Chinese campaign with their allies in the 1943–45 Burma Campaign. The campaign ended in an Allied victory.', 1943, 10, NULL, 1945, 3, NULL, 'month', 'October 1943 – March 1945', 41, 'https://en.wikipedia.org/wiki/Battle_of_Northern_Burma_and_Western_Yunnan'),
  ('Q2119306', '1947 Thai coup d''état', 'The coup d''état of 8 November 1947 (Thai: รัฐประหาร 8 พฤศจิกายน พ.ศ. 2490) was a military coup d''état that took place in Thailand on the evening of 8 November 1947 and ended in the early morning hours of 9 November.', 1947, 11, 8, 1947, 11, 8, 'day', '8 November 1947', 34, 'https://en.wikipedia.org/wiki/1947_Thai_coup_d''%C3%A9tat'),
  ('Q8663', 'Korean War', 'The Korean War (25 June 1950 – 27 July 1953) was an armed conflict fought on the Korean Peninsula between North Korea (Democratic People''s Republic of Korea; DPRK) and South Korea (Republic of Korea; ROK) and their allies. North Korea was supported by China and the Soviet Union, while South Korea was supported by the United Nations led by the United States under the auspices of the United Nations Command (UNC).', 1950, 6, 25, 1953, 7, 27, 'day', '25 June 1950 – 27 July 1953', 94, 'https://en.wikipedia.org/wiki/Korean_War'),
  ('Q6585263', '1951 Thai coup d''état', 'Thailand''s Silent Coup of 29 November 1951, otherwise known as the Radio Coup, consolidated the military''s hold on the country. It reinstated the 1932 constitution, which effectively eliminated the Senate, established a unicameral legislature composed equally of elected and government-appointed members, and allowed serving military officers to supplement their commands with important ministerial portfolios.', 1951, 11, 29, NULL, NULL, NULL, 'day', '29 November 1951', 30, 'https://en.wikipedia.org/wiki/Silent_Coup_(Thailand)'),
  ('Q2119300', '1957 Thai coup d''état', 'On 16 September 1957, Thailand experienced a military coup led by Field Marshal Sarit Thanarat. This bloodless coup ended the government of Prime Minister Plaek Phibunsongkhram.', 1957, 9, 16, NULL, NULL, NULL, 'day', '16 September 1957', 34, 'https://en.wikipedia.org/wiki/1957_Thai_coup_d''%C3%A9tat'),
  ('Q877450', 'Laotian Civil War', 'The Laotian Civil War was waged between the Communist Pathet Lao and the Royal Lao Government from 23 May 1959 to 2 December 1975. The Kingdom of Laos was a covert theater during the Vietnam War with both sides receiving heavy external support in a proxy war between the global Cold War superpowers.', 1959, 5, 23, 1975, 12, 2, 'day', '23 May 1959 – 2 December 1975', 71, 'https://en.wikipedia.org/wiki/Laotian_Civil_War'),
  ('Q3042723', 'ASEAN Declaration', 'The ASEAN Declaration, commonly known as the Bangkok Declaration, is the founding charter of the Association of Southeast Asian Nations (ASEAN). Signed on 8 August 1967 by the foreign ministers of Indonesia, Malaysia, the Philippines, Singapore, and Thailand in Bangkok, the capital city of Thailand, it formally established the Association to promote regional cooperation in economic, social, cultural, technical, and administrative fields, and to foster regional peace and stability through adherence to the United Nations Charter and the rule of law.', 1967, 8, 8, NULL, NULL, NULL, 'day', '8 August 1967', 57, 'https://en.wikipedia.org/wiki/ASEAN_Declaration'),
  ('Q82542', 'Tet Offensive', 'The Tet Offensive was both a major escalation and one of the largest military campaigns of the Vietnam War. The North Vietnamese People''s Army of Vietnam (PAVN) and the Viet Cong (VC) launched a surprise attack on 30 and 31 January 1968 against the forces of the South Vietnamese Army of the Republic of Vietnam (ARVN), the United States Armed Forces and their allies, targeting military and civilian command and control centers throughout South Vietnam.', 1968, 1, 30, 1968, 9, 23, 'day', '30 January 1968 – 23 September 1968', 72, 'https://en.wikipedia.org/wiki/Tet_Offensive'),
  ('Q4575745', '1973 Thai popular uprising', 'The popular uprising of 14 October 1973 (Thai: เหตุการณ์ 14 ตุลา, RTGS: Hetkan Sip-Si Tula, lit. ''October 14 Event''; also วันมหาวิปโยค, RTGS: Wan Maha Wippayok, lit. ''Day of Great Sorrow'') was a watershed event in Thailand''s history. The uprising resulted in the end of the ruling military dictatorship of anti-communist Thanom Kittikachorn and altered the Thai political system.', 1973, 10, 14, NULL, NULL, NULL, 'day', '14 October 1973', 51, 'https://en.wikipedia.org/wiki/1973_Thai_popular_uprising'),
  ('Q8740', 'Vietnam War', 'The Vietnam War (c. 1955 – 30 April 1975) was an armed conflict in Vietnam, Laos, and Cambodia fought between North Vietnam (Democratic Republic of Vietnam) and South Vietnam (Republic of Vietnam) and their allies. North Vietnam was supported by the Soviet Union and China, while South Vietnam was supported by the United States and other anti-communist nations.', 1975, 4, 30, 1975, 4, 30, 'day', '30 April 1975', 97, 'https://en.wikipedia.org/wiki/Vietnam_War'),
  ('Q796498', 'Third Indochina War', 'The Third Indochina War was a series of interconnected military conflicts among the various communist factions over strategic influence in mainland Southeast Asia after communist victory in South Vietnam, Laos, and Cambodia in 1975. The conflict primarily started due to continued raids and incursions by the Khmer Rouge into Vietnamese territory that they sought to retake.', 1975, 5, 1, 1991, 10, 23, 'day', '1 May 1975 – 23 October 1991', 53, 'https://en.wikipedia.org/wiki/Third_Indochina_War'),
  ('Q1907348', 'Thammasat University massacre', 'The 6 October 1976 massacre, also known as the 6 October event (Thai: เหตุการณ์ 6 ตุลา RTGS: Hetkan Hok Tula) in Thailand, was a violent crackdown by Thai police and lynching by right-wing paramilitaries and bystanders against leftist protesters who had occupied Bangkok''s Thammasat University and the adjacent Sanam Luang, on 6 October 1976. Prior to the massacre, thousands of leftists, including students, workers and others, had been holding ongoing demonstrations against the return of exiled former Prime Minister Thanom Kittikachorn to Thailand since mid-September.', 1976, 10, 6, NULL, NULL, NULL, 'day', '6 October 1976', 57, 'https://en.wikipedia.org/wiki/6_October_1976_massacre'),
  ('Q5348315', 'EgyptAir Flight 864', 'EgyptAir Flight 864 was an international scheduled passenger flight from Rome Fiumicino Airport to Tokyo International Airport, via Cairo, Bombay, and Bangkok. On 25 December 1976, the Boeing 707 crashed into an industrial complex in Bangkok.', 1976, 12, 25, NULL, NULL, NULL, 'day', '25 December 1976', 50, 'https://en.wikipedia.org/wiki/EgyptAir_Flight_864'),
  ('Q65086996', '1977 Thai coup d''état', 'The October 1977 Thai coup d''état was a bloodless military coup which took place in Thailand on 20 October 1977, staged by the Royal Thai Armed Forces (RTAF). The coup was carried out under the nominal authority of Admiral Sangad Chaloryu of the Royal Thai Navy, head of the National Administrative Reform Council (NARC), but it was effectively led by General Kriangsak Chamanan of the Royal Thai Army, Supreme Commander of the RTAF. It led to the deposition of Prime Minister Thanin Kraivichien, who assumed the office following the 1976 coup d''état (which was also led by Admiral Sangad and…', 1977, 10, 20, NULL, NULL, NULL, 'day', '20 October 1977', 37, 'https://en.wikipedia.org/wiki/October_1977_Thai_coup_d''%C3%A9tat'),
  ('Q7928485', 'Vietnam Airlines Flight 831', 'Vietnam Airlines Flight 831, a Tupolev Tu-134, crashed in a rice field 6 kilometres (3.7 miles) N of Bangkok International Airport, while operating a flight from Hanoi, Vietnam to Bangkok, Thailand, on 9 September 1988. The cause of the accident is undetermined; however, the pilots reported the aircraft may have been struck by lightning as it approached to land.', 1988, 9, 9, NULL, NULL, NULL, 'day', '9 September 1988', 47, 'https://en.wikipedia.org/wiki/Vietnam_Airlines_Flight_831'),
  ('Q635533', 'Cambodian–Vietnamese War', 'The Cambodian–Vietnamese War was an armed conflict from 1978 to 1989 between Democratic Kampuchea and the Socialist Republic of Vietnam, and their respective allies. It began in December 1978, with smaller clashes culminating into a Vietnamese invasion of Cambodia which toppled the Khmer Rouge regime and ended in 1989 with the withdrawal of Vietnamese forces from Cambodia.', 1989, 9, 26, 1991, 10, 23, 'day', '26 September 1989 – 23 October 1991', 73, 'https://en.wikipedia.org/wiki/Cambodian%E2%80%93Vietnamese_War'),
  ('Q675546', 'Lauda Air Flight 004', 'Lauda Air Flight 004 was a regularly scheduled international passenger flight from Hong Kong, via Bangkok, Thailand, to Vienna, Austria. On 26 May 1991, the Boeing 767 operating the route crashed following an uncommanded deployment of the thrust reverser on the No.', 1991, 5, 26, NULL, NULL, NULL, 'day', '26 May 1991', 61, 'https://en.wikipedia.org/wiki/Lauda_Air_Flight_004'),
  ('Q6585266', '1991 Thai coup d''état', 'The 1991 Thai coup d''état was a military coup against the democratic Chatichai government, carried out by Thai military leaders on 23 February. Although the figure head was Sunthorn Kongsompong, there was a military influence from military leaders, Chavalit Yongchaiyudh, Suchinda Kraprayoon, and Kaset Rojananil in the conflict.', 1991, 2, 23, NULL, NULL, NULL, 'day', '23 February 1991', 37, 'https://en.wikipedia.org/wiki/1991_Thai_coup_d''%C3%A9tat'),
  ('Q1037676', 'Black May', 'Black May (Thai: พฤษภาทมิฬ; RTGS: Phruetsapha Thamin), also known as "Bloody May", was a series of mass protests and subsequent crackdowns by the Thai military and royal police in Bangkok in May 1992. A rally of over 200,000 people led by Chamlong Srimuang was held on 17 May, caused by the extending of the military regime of Suchinda Kraprayoon, the 1991 Thai coup d''état leader.', 1992, 5, NULL, 1992, 5, 20, 'month', 'May 1992 – 20 May 1992', 51, 'https://en.wikipedia.org/wiki/Black_May_(Thailand)'),
  ('Q612396', 'Thai Airways International Flight 261', 'Thai Airways International Flight 261 was a scheduled domestic passenger flight from Bangkok''s Don Mueang International Airport to Surat Thani International Airport in Surat Thani, Thailand. The flight was operated by Thai Airways International, the flag carrier of Thailand.', 1998, 12, 11, NULL, NULL, NULL, 'day', '11 December 1998', 56, 'https://en.wikipedia.org/wiki/Thai_Airways_International_Flight_261'),
  ('Q7266508', 'Qantas Flight 1', 'Qantas Flight 1 (QF1/QFA1) was a Qantas passenger flight between Sydney and London with a stop in Bangkok-Don Mueang. On 23 September 1999, the Boeing 747-400 operating as Flight 1 had departed from Sydney that day, and was involved in a runway overrun accident at Don Mueang International Airport in Bangkok as it was landing for a stopover.', 1999, 9, 23, NULL, NULL, NULL, 'day', '23 September 1999', 47, 'https://en.wikipedia.org/wiki/Qantas_Flight_1'),
  ('Q60638', 'Thai Airways International Flight 114', 'On 3 March 2001, Thai Airways International Flight 114 exploded at gate 62 of Don Muang International Airport in Bangkok, Thailand, killing one person and injuring seven other people. Five cabin attendants, two baggage loaders, and a load control supervisor were preparing the Boeing 737-400 for a flight from Bangkok to Chiang Mai before the passengers were boarded.', 2001, 3, 3, NULL, NULL, NULL, 'day', '3 March 2001', 50, 'https://en.wikipedia.org/wiki/Thai_Airways_International_Flight_114'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q1094356', 'South Thailand insurgency', 'The Southern Thailand insurgency (Thai: ความไม่สงบในชายแดนภาคใต้ของประเทศไทย; Malay: Pemberontakan di Thailand Selatan) is an ongoing conflict centered in southern Thailand. It originated in 1948 as a separatist insurgency in the historical Malay Patani Region, made up of the three southernmost provinces of Thailand and parts of a fourth, but has become more complex and increasingly violent since the early 2000s from drug cartels, oil smuggling networks, and sometimes pirate raids.', 2004, 10, 25, NULL, NULL, NULL, 'day', '25 October 2004', 60, 'https://en.wikipedia.org/wiki/Southern_Thailand_insurgency'),
  ('Q860423', '2006 Thai coup d''état', 'The 2006 Thai coup d''état took place on 19 September 2006, when the Royal Thai Army staged a coup d''état against the elected caretaker government of Prime Minister Thaksin Shinawatra. The coup d''état, which was Thailand''s first non-constitutional change of government in fifteen years since the 1991 Thai coup d''état, followed a year-long political crisis involving Thaksin, his allies, and political opponents and occurred less than a month before nationwide House elections were scheduled to be held.', 2006, 9, 19, NULL, NULL, NULL, 'day', '19 September 2006', 65, 'https://en.wikipedia.org/wiki/2006_Thai_coup_d''%C3%A9tat'),
  ('Q460476', 'One-Two-GO Airlines Flight 269', 'One-Two-Go Airlines Flight 269 (OG269/OTG269) was a scheduled domestic passenger flight from Bangkok to Phuket, Thailand. On 16 September 2007, about 15:41 ICT, the McDonnell Douglas MD-82 operating the flight crashed into an embankment beside runway 27 at Phuket International Airport (HKT) bursting into flames upon impact during an attempted go-around after an aborted landing, killing 90 of the 130 people on board (including one person who died of burn injuries several days after the crash).', 2007, 9, 16, NULL, NULL, NULL, 'day', '16 September 2007', 63, 'https://en.wikipedia.org/wiki/One-Two-Go_Airlines_Flight_269'),
  ('Q2643482', '2010 floods in Thailand and north Malaysia', 'A series of flash floods hit different areas of Thailand and Malaysia in 2010. Separate but related floods began in Northeast and Central Thailand (per the six-region definition) in early October due to abnormally late monsoon moisture over the Bay of Bengal, overflowed the Chao Phraya where the rivers meet, and affected Bangkok, and in the South were triggered by a tropical depression about two weeks later, and were later aggravated by related La Niña monsoon rains.', 2010, 10, NULL, NULL, NULL, NULL, 'month', 'October 2010', 37, 'https://en.wikipedia.org/wiki/2010_Thailand%E2%80%93Malaysia_floods'),
  ('Q150495', '2011 Tarlay earthquake', 'The 2011 Shan earthquake occurred on 24 March in Shan State, Myanmar. The earthquake measured Mw 6.8 and had an epicenter northwest of the border between Myanmar, Thailand and Laos.', 2011, 3, 24, NULL, NULL, NULL, 'day', '24 March 2011', 61, 'https://en.wikipedia.org/wiki/2011_Shan_earthquake'),
  ('Q181481', '2011 Thailand floods', 'Severe flooding occurred during the 2011 monsoon season in Thailand. The flooding began at the end of July triggered by the landfall of Tropical Storm Nock-ten.', 2011, 7, 31, 2011, 12, NULL, 'day', '31 July 2011 – December 2011', 57, 'https://en.wikipedia.org/wiki/2011_Thailand_floods'),
  ('Q6161350', 'Mekong River massacre', 'The Mekong River massacre occurred on the morning of 5 October 2011, when two Chinese cargo ships were attacked on a stretch of the Mekong River in the Golden Triangle region on the borders of Myanmar (Burma) and Thailand. All 13 crew members on both ships were killed and dumped in the river.', 2011, 10, 5, NULL, NULL, NULL, 'day', '5 October 2011', 39, 'https://en.wikipedia.org/wiki/Mekong_River_massacre'),
  ('Q15243731', '2013–14 Thai political crisis', 'The 2013–2014 Thai political crisis was a period of political instability in Thailand. Anti-government protests took place between November 2013 and May 2014, organised by the People''s Democratic Reform Committee (PDRC), a political pressure group led by former Democrat Party parliamentary representative (MP) Suthep Thaugsuban.', 2013, 10, 31, NULL, NULL, NULL, 'day', '31 October 2013', 58, 'https://en.wikipedia.org/wiki/2013%E2%80%932014_Thai_political_crisis'),
  ('Q16914766', '2014 Thai coup d''état', 'On 22 May 2014, the Royal Thai Armed Forces, led by General Prayut Chan-o-cha, the commander-in-chief of the Royal Thai Army, launched a coup d''état, the twelfth since the country''s first coup in 1932, against the caretaker government following six months of political crisis. The military established a junta called the National Council for Peace and Order (NCPO) to govern the nation.', 2014, 5, 22, NULL, NULL, NULL, 'day', '22 May 2014', 65, 'https://en.wikipedia.org/wiki/2014_Thai_coup_d''%C3%A9tat'),
  ('Q26260566', 'August 2016 Thailand bombings', 'On 11 August 2016, two bombs exploded in the Thai resort town of Hua Hin. One person was killed and 23, many of them tourists, were injured.', 2016, 8, NULL, NULL, NULL, NULL, 'month', 'August 2016', 41, 'https://en.wikipedia.org/wiki/August_2016_Thailand_bombings'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q97667436', '2020–2021 Thai protests', 'In Thailand, protests began in early 2020 with demonstrations against the government of Prime Minister Prayut Chan-o-cha. They later expanded to include the unprecedented demands for reform of the Thai monarchy.', 2020, 2, NULL, 2021, 12, NULL, 'month', 'February 2020 – December 2021', 62, 'https://en.wikipedia.org/wiki/2020%E2%80%932021_Thai_protests'),
  ('Q121009477', 'Sungai Kolok fireworks disaster', 'The Sungai Kolok fireworks disaster was a catastrophic fireworks explosion that occurred at a warehouse on 29 July 2023 in Sungai Kolok, Thailand, killing at least 12 and injuring at least 118, and destroying at least 200 homes and businesses.', 2023, 7, 29, NULL, NULL, NULL, 'day', '29 July 2023', 34, 'https://en.wikipedia.org/wiki/Sungai_Kolok_fireworks_disaster');
